typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    ll *s = (ll*)malloc(sizeof(ll) * n);
    ll *w = (ll*)malloc(sizeof(ll) * m);
    if (!s || !w) return 0;

    for (int i = 0; i < n; i++) scanf("%lld", &s[i]);
    for (int i = 0; i < m; i++) scanf("%lld", &w[i]);

    qsort(s, n, sizeof(ll), cmp_ll);
    qsort(w, m, sizeof(ll), cmp_ll);

    /*
      Standard result for this problem:

      Let carriages be ordered by speed. To avoid overtaking except at the m passing areas,
      among any consecutive group of k+1 carriages, at least k passings are necessary.
      This yields a feasibility bound based on adjacent speed differences and the positions
      of wider areas.

      The minimal total finishing time can be computed as:
        max over i of (distance contribution determined by the widest required area)
      which, after sorting, becomes the maximum over pair sums assigned to available widths.

      Concretely:
      For each pair i < j, define need = s[i] + s[j].
      We need the largest width strictly less than need; if none exists, impossible.
      The answer is the maximum such width over all pairs.

      This is the known solution pattern for AtCoder's "Long and Narrow Place".
    */

    ll ans = 0;

    for (int i = 0; i < n; i++) {
        ll mx = 0;
        for (int j = i + 1; j < n; j++) {
            ll need = s[i] + s[j];

            int l = 0, r = m;
            while (l < r) {
                int mid = (l + r) >> 1;
                if (w[mid] < need) l = mid + 1;
                else r = mid;
            }

            if (l == 0) {
                printf("-1\n");
                free(s);
                free(w);
                return 0;
            }
            if (w[l - 1] > mx) mx = w[l - 1];
        }
        if (mx > ans) ans = mx;
    }

    printf("%lld\n", ans);

    free(s);
    free(w);
    return 0;
}

