/*
 * AOJ/ICPC style problem:
 * There are n carriages moving on a 1D narrow road from start(0) to goal(L).
 * Carriage i has speed Si and starts at time i-1 (one per minute / unit time).
 * They cannot overtake except at m passing points on the road.
 * Find the minimum time from the departure of the first carriage until all reach the goal.
 *
 * Key observation:
 * If a faster carriage catches a slower one between passing points, it must slow down and join it.
 * Therefore, between two consecutive passing points, the order cannot change.
 * Reordering is possible only exactly at passing points.
 *
 * Dynamic programming over segments:
 * Let positions be x[0]=0, x[1..m]=passing points, x[m+1]=L.
 * After each passing point, we may reorder arbitrarily.
 *
 * For a segment of length d, if a block of carriages k..i (in current order) traverses it
 * without passing, then they all leave the segment at the same time:
 *   max_{t=k..i} (startTime[t] + d / S_t)
 * where startTime[t] is the time that carriage t enters the segment.
 *
 * DP:
 * dp[i] = minimal possible time by which the first i carriages have finished current prefix,
 *         assuming after the current passing point they may be reordered optimally.
 *
 * Transition for one segment of length d:
 *   ndp[i] = min over k<=i of max(dp[k-1], max_{t=k..i}(dp order?))
 *
 * More concretely, after a passing point we can choose any partition of the i carriages into blocks;
 * each block traverses next segment in nondecreasing finish time determined by the latest member.
 *
 * Standard recurrence:
 *   ndp[i] = min_{1<=k<=i} max(ndp[k-1], dpPrevForCarriages k..i over segment)
 *
 * Since after every passing point arbitrary reorder is allowed, the only thing that matters is
 * the multiset of arrival times at that point. Sorting them increasingly is optimal.
 *
 * So maintain times a[1..n] sorted increasingly: earliest available carriage entries to next segment.
 * For segment length d, compute new sorted arrival times b[1..n] by:
 *   b[i] = min over k<=i of max(b[k-1], max_{t=k..i}(a[t] + d/S_t_sorted?))
 *
 * But speeds belong to carriages, and after reordering, we can assign order on the segment.
 * To minimize, faster carriages should be later? Actually within a no-passing block, effective
 * finish time is max(entry + d/speed). Since block members all finish together at that max.
 * We may permute carriages arbitrarily at passing points, so to minimize sorted completion times
 * after a segment, assign smaller entry times to slower carriages (rearrangement inequality style).
 * Thus sort speeds descending by travel time? Equivalent sort by d/Si decreasing = slower first.
 * Since d is common, sort by speed ascending once.
 *
 * Then initial entry times are departures 0,1,2,...,n-1 paired with speeds ascending.
 * Process each segment with DP preserving sorted completion times.
 *
 * Recurrence with speeds ascending (slow to fast), cost_i = d / speed[i]:
 * Given sorted entry times a[1..n], produce sorted exit times b[1..n]:
 *   b[0] = -INF
 *   b[i] = min_{k=1..i} max( b[k-1], max_{t=k..i}( a[t] + cost_t ) )
 * Here block k..i exits together.
 *
 * Complexity O((m+1) * n^2).
 *
 * Input format assumed:
 * multiple test cases:
 *   n m L
 *   S1 ... Sn
 *   P1 ... Pm
 * terminated by n=m=L=0
 *
 * Output minimal total time for each test case.
 *
 * This matches the classic "Long and Narrow" problem.
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            String first = fs.next();
            if (first == null) break;
            int n = Integer.parseInt(first);
            int m = fs.nextInt();
            double L = fs.nextDouble();

            if (n == 0 && m == 0 && L == 0) break;

            double[] s = new double[n];
            for (int i = 0; i < n; i++) s[i] = fs.nextDouble();
            Arrays.sort(s); // ascending speed: slow to fast

            double[] pos = new double[m + 2];
            pos[0] = 0.0;
            for (int i = 1; i <= m; i++) pos[i] = fs.nextDouble();
            pos[m + 1] = L;
            Arrays.sort(pos);

            double[] a = new double[n + 1]; // 1-indexed sorted available times
            for (int i = 1; i <= n; i++) a[i] = i - 1; // departures 0,1,2,...

            for (int seg = 0; seg <= m; seg++) {
                double d = pos[seg + 1] - pos[seg];
                double[] val = new double[n + 1];
                for (int i = 1; i <= n; i++) val[i] = a[i] + d / s[i];

                double[] b = new double[n + 1];
                b[0] = -1e100;
                for (int i = 1; i <= n; i++) {
                    double best = Double.POSITIVE_INFINITY;
                    double mx = -1e100;
                    for (int k = i; k >= 1; k--) {
                        mx = Math.max(mx, val[k]);
                        best = Math.min(best, Math.max(b[k - 1], mx));
                    }
                    b[i] = best;
                }
                a = b;
            }

            out.append(String.format(Locale.US, "%.10f%n", a[n]));
        }

        System.out.print(out.toString());
    }
}

